import{d as g,C as n,o as d,c as h,E as o,a3 as r}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"家人卦","description":"风火家人","frontmatter":{"title":"家人卦","description":"风火家人","category":"hexagram","aliases":["家人","风火家人"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-37.md","filePath":"yijing/hexagrams/hexagram-37.md","lastUpdated":1787800334000}'),p={name:"yijing/hexagrams/hexagram-37.md"},b=g({...p,setup(u){const i=[{id:"xian",term:"闲",pinyin:"xián",meaning:"门内有木，本义为门闩、栅栏；引申为防范、规范、划定界限。",context:"初九「闲有家」：进门先立规矩，趁风气未坏时划清界限。"},{id:"wuyousui",term:"无攸遂",pinyin:"wú yōu suì",meaning:"无所专断，不擅自做主。攸为「所」，遂为「成、专」。",context:"六二守本位：知道自己管什么，不抢别人的事做。"},{id:"zhongkui",term:"中馈",pinyin:"zhōng kuì",meaning:"家中饮食之事；引申为日常经营、内务治理。",context:"「在中馈」：把家的一日三餐、日常循环经营好。"},{id:"he",term:"嗃嗃",pinyin:"hè hè",meaning:"严厉的斥责声，家法严明的样子。",context:"九三「家人嗃嗃」：宁可严一点，不可松到失节。"},{id:"xixi",term:"嘻嘻",pinyin:"xī xī",meaning:"嬉笑放纵、没有规矩的样子。",context:"九三「妇子嘻嘻，终吝」：一时欢乐，失家节，终有憾惜。"},{id:"fujia",term:"富家",pinyin:"fù jiā",meaning:"使家富足。富字拆解：宀（家）+一（一）+口（人口）+田（耕耘）——在家里守住那个一，从日常开始持续耕耘。",context:"六四「富家大吉」：富是日积月累，不是一次拥有。"},{id:"jia",term:"假",pinyin:"gé",meaning:"至、到达。亦读 jiǎ。",context:"九五「王假有家」：君主以德至于家，以身作则到家道之正。"},{id:"wuxu",term:"勿恤",pinyin:"wù xù",meaning:"不必忧虑。恤为忧虑、体恤。",context:"九五「勿恤，吉」：家道已成，从管控转为信任，可以放心。"},{id:"youfu",term:"有孚"},{id:"weiru",term:"威如",pinyin:"wēi rú",meaning:"威严自然显现的样子。",context:"上九「威如之吉，反身之谓也」：威在外求不到，在反身自省。"},{id:"fanshen",term:"反身",pinyin:"fǎn shēn",meaning:"反求诸己、反身自省。",context:"治家的最高境界不是管人，是修身；自己做到了，威自然立。"}],a=[{position:"初九",type:"yang",text:"闲有家，悔亡。",xiang:"闲有家，志未变也。",textModern:"进门先立规矩（闲），趁志向风气未变时划清界限，悔恨自然消亡。",xiangModern:"及早立规矩，是因为风气尚未改变——规矩要立在早期，等到积习难返就晚了。"},{position:"六二",type:"yin",text:"无攸遂，在中馈，贞吉。",xiang:"六二之吉，顺以巽也。",textModern:"不擅自专断，安于中馈——把家中日常经营好，守正而吉。",xiangModern:"六二的吉，来自柔顺恭巽：守本位而不越位，顺其位而行其事。"},{position:"九三",type:"yang",text:"家人嗃嗃，悔厉吉。妇子嘻嘻，终吝。",xiang:"家人嗃嗃，未失也。妇子嘻嘻，失家节也。",textModern:"治家过于严厉（嗃嗃），虽有悔恨与危厉，终究吉祥；若任由妇子嬉笑放纵（嘻嘻），最终必有憾惜。",xiangModern:"治家严厉，家道未失；嬉笑放纵，则失去了家的节度。"},{position:"六四",type:"yin",text:"富家，大吉。",xiang:"富家大吉，顺在位也。",textModern:"让家富足起来，大吉。",xiangModern:"富家之所以大吉，是因为柔顺而安于其位——在自己的位置上持续耕耘。"},{position:"九五",type:"yang",text:"王假有家，勿恤，吉。",xiang:"王假有家，交相爱也。",textModern:"君主以身作则、以德至于家，不必忧虑，吉。",xiangModern:"以德至于家道，家人之间彼此相爱，而不是靠管控维持。"},{position:"上九",type:"yang",text:"有孚威如，终吉。",xiang:"威如之吉，反身之谓也。",textModern:"有诚信为根基，威严自然显现，最终吉祥。",xiangModern:"威严之吉，说的是反身自省——威不是外求的，是从修身而来的。"}];return(m,t)=>{const e=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),s=n("DaoKeywordCards");return d(),h("div",null,[o(e,{name:"家人",fullName:"风火家人",upper:"☴",lower:"☲",guaCi:"家人，利女贞。",pinyin:["jiā","rén"],element:"木",direction:"东南",insight:"火在内燃烧，风由内生出——家之象也；内明外顺，德风自内而出，正家而天下定。",guaSlug:"37fenghuojiaren",lines:a}),t[0]||(t[0]=r('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>风自火出，家人。君子以言有物而行有恒。</p><p>火在内燃烧，风由内生、向外扩散——家内之德如风，会吹到家外去。君子由此悟到两点：</p><ul><li><strong>言有物</strong> → 说话要有实质，不空谈。家的影响力，从嘴里说出的每一句话开始累积。</li><li><strong>行有恒</strong> → 行事要有恒常，不朝三暮四。家风不是靠说教立的，是靠一言一行的重复。</li></ul><p>分形结构：</p><ul><li>言有物（言语）→ 微观：说到做到，字字有分量</li><li>行有恒（行为）→ 宏观：日日如此，久久成风</li></ul><p>家风就是这样立起来的：不在惊天动地，而在言必有物、行必有恒。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>家人，女正位乎内，男正位乎外。男女正，天地之大义也。家人有严君焉，父母之谓也。父父子子，兄兄弟弟，夫夫妇妇，而家道正。正家而天下定矣。</p><p>逐句释义：</p><ul><li><strong>女正位乎内，男正位乎外，男女正，天地之大义也</strong> —— 家内家外各正其位，是天地间的大义。这里的「内」「外」不是僵化的性别分工，而是说一个家需要各守其位、各尽其分。</li><li><strong>家人有严君焉，父母之谓也</strong> —— 家里有威严的「君长」，说的就是父母。治家需要父母立起这个「严」——不是凶，是节度与原则。</li><li><strong>父父子子，兄兄弟弟，夫夫妇妇</strong> —— 每个身份都做足本分：做父亲的像父亲，做儿子的像儿子，各安其位，家道自然正。</li><li><strong>正家而天下定矣</strong> —— 家道正了，天下就定了。家是最小的国，国是最大的家——治天下的功夫，从治家开始。</li></ul><blockquote><p><strong>核心句：正家而天下定矣。</strong> 家道正，则天下定——家不是退隐的角落，是治国的练习场。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',13)),o(l,{element:"木",guaSlug:"37fenghuojiaren",glossary:i,items:a}),t[1]||(t[1]=r('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初九-·-闲有家-悔亡" tabindex="-1">初九 · 闲有家，悔亡 <a class="header-anchor" href="#初九-·-闲有家-悔亡" aria-label="Permalink to &quot;初九 · 闲有家，悔亡&quot;">​</a></h3><ul><li><strong>闲</strong> → 门内有木，门闩、栅栏；引申为防范、规范、界限</li><li><strong>有家</strong> → 有家之初，先立规矩</li><li><strong>悔亡</strong> → 悔恨消亡</li></ul><p>初九是家人卦的第一爻，阳爻居初位，是「开门第一课」——进门先立规矩。门闩的作用不是把门封死，而是让门知道何时开、何时关。规矩也是如此：不是压制，是划定边界。</p><p><strong>「志未变也」</strong>：趁志向未变、家风未坏之时立规，最容易。规矩要在早期立——等习惯养成、积习难返时再改，就难了。</p><blockquote><p>核心洞见：门闩不是锁，是开关的秩序。立规矩要趁早，这是治家的第一道功夫。</p></blockquote><h3 id="六二-·-无攸遂-在中馈-贞吉" tabindex="-1">六二 · 无攸遂，在中馈，贞吉 <a class="header-anchor" href="#六二-·-无攸遂-在中馈-贞吉" aria-label="Permalink to &quot;六二 · 无攸遂，在中馈，贞吉&quot;">​</a></h3><ul><li><strong>无攸遂</strong> → 无所专断，不擅自做主（攸：所；遂：成、专）</li><li><strong>中馈</strong> → 家中饮食之事，引申为日常经营、内务治理</li><li><strong>贞吉</strong> → 守正而吉</li></ul><p>六二阴爻居中得正，是家中的主内之位。<strong>「无攸遂」不是没主见，是不越位</strong>——知道自己管什么，不抢别人的事做。<strong>「中馈」不只是做饭</strong>，是把家里的一日三餐、日常循环经营好。</p><p>守本位，是六二给整个家的贡献：田在脚下，先把脚下的田耕好。</p><blockquote><p>六二教「守位」：把锅碗瓢盆经营好，比空谈大局更接近家道之正。</p></blockquote><h3 id="九三-·-家人嗃嗃-悔厉吉。妇子嘻嘻-终吝" tabindex="-1">九三 · 家人嗃嗃，悔厉吉。妇子嘻嘻，终吝 <a class="header-anchor" href="#九三-·-家人嗃嗃-悔厉吉。妇子嘻嘻-终吝" aria-label="Permalink to &quot;九三 · 家人嗃嗃，悔厉吉。妇子嘻嘻，终吝&quot;">​</a></h3><ul><li><strong>嗃嗃</strong> → 严厉的斥责声，家法严明的样子</li><li><strong>悔厉吉</strong> → 有过悔、有危厉，但终究吉</li><li><strong>嘻嘻</strong> → 嬉笑放纵、没有规矩的样子</li><li><strong>终吝</strong> → 最终有憾惜</li></ul><p>九三是严与松的分水岭。治家过严（嗃嗃），虽然家人感到严厉，有过悔与危厉，但家道不失，终吉；治家过松（嘻嘻），一时欢乐，却失家节，终吝。</p><p><strong>严有度，松有祸</strong>：宁可严一点，不可松到失节。但也要记得，严的目的是「节」，不是控制——严是为了守住边界，不是为了发泄权威。</p><blockquote><p>九三教「拿捏」：嗃嗃之严是暂时的痛，嘻嘻之松是长久的漏。两者相权，宁严勿松。</p></blockquote><h3 id="六四-·-富家-大吉" tabindex="-1">六四 · 富家，大吉 <a class="header-anchor" href="#六四-·-富家-大吉" aria-label="Permalink to &quot;六四 · 富家，大吉&quot;">​</a></h3><ul><li><strong>富</strong> → 宀（家）+ 一（一）+ 口（人口）+ 田（田产）——在家里守住那个一，从日常开始持续耕耘</li><li><strong>大吉</strong> → 大吉之象</li></ul><p>富字拆解：<strong>宀</strong>是屋顶，<strong>一</strong>是那个核心的一，<strong>口</strong>是人口、吃饭的人，<strong>田</strong>是田产、耕耘之地。富家不是发财，是让家里的人口、田产围绕那个「一」运转起来——守住那个一，从日常开始持续耕耘。</p><p>六四阴爻居阴位，得正。富家的功夫在「顺在位」：不抢位、不越位，在自己在的位置上持续耕耘。<strong>财富不是一次性拥有的结果，是日日耕耘的积累。</strong></p><blockquote><p>六四教「耕耘」：富字的全部秘密，就是「宀+一+口+田」——在家里守住那个一，一天一天把田耕下去。</p></blockquote><h3 id="九五-·-王假有家-勿恤-吉" tabindex="-1">九五 · 王假有家，勿恤，吉 <a class="header-anchor" href="#九五-·-王假有家-勿恤-吉" aria-label="Permalink to &quot;九五 · 王假有家，勿恤，吉&quot;">​</a></h3><ul><li><strong>假</strong> → 至、到达（读 gé）</li><li><strong>王假有家</strong> → 君主以德临其家，以身作则到达「有家」之境</li><li><strong>勿恤</strong> → 不必忧虑</li><li><strong>吉</strong> → 吉</li></ul><p>九五阳爻居尊位，是一家之主。此前各爻都在立规矩、守本位、拿捏严松，到九五已「假」家——真正到达家的境界。此时不必再忧恤（勿恤），因为家道已成，可以放心信任。</p><p><strong>从管控到信任</strong>：初九立规，是管控的起点；九五勿恤，是信任的到达。信任不是不管，是管到位之后的放手。</p><p><strong>「交相爱也」</strong>——到这一步，维系家的已经不是规矩，而是爱。</p><blockquote><p>九五教「放手」：从管控到信任，中间隔着一路的耕耘。管到位了，才配得上放手。</p></blockquote><h3 id="上九-·-有孚威如-终吉" tabindex="-1">上九 · 有孚威如，终吉 <a class="header-anchor" href="#上九-·-有孚威如-终吉" aria-label="Permalink to &quot;上九 · 有孚威如，终吉&quot;">​</a></h3><ul><li><strong>有孚</strong> → 有诚信为根基</li><li><strong>威如</strong> → 威严自然显现</li><li><strong>终吉</strong> → 最终吉祥</li></ul><p>上九居卦之终，是家道的收束。<strong>「威如」不是摆出来的威严，是「有孚」之后自然生出的威严</strong>——内心有诚信、行为有常，威严自来。</p><p><strong>「反身之谓也」</strong>——威不在外求，在反身自省。自己做到了，威自然立；自己没做到，摆再多架子也没用。</p><blockquote><p>核心洞见：孚为根基，威自现。治家的最高境界，不是管人，是修身。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',33)),o(s,{title:"字词释义",items:[{term:"闲",pinyin:["xián"],meaning:"门内有木，本义为门闩、栅栏；引申为防范、规范、划定界限。「闲有家」即进门先立规矩。"},{term:"中馈",pinyin:["zhōng","kuì"],meaning:"家中饮食之事；引申为日常经营、内务治理。「在中馈」即把家的一日三餐、日常循环经营好。"},{term:"无攸遂",pinyin:["wú","yōu","suì"],meaning:"无所专断，不擅自做主。攸为「所」，遂为「成、专」。"},{term:"嗃嗃",pinyin:["hè","hè"],meaning:"严厉的斥责声，家法严明的样子。"},{term:"嘻嘻",pinyin:["xī","xī"],meaning:"嬉笑放纵、没有规矩的样子。「妇子嘻嘻，终吝」：一时欢乐，失家节，终有憾惜。"},{term:"富家",pinyin:["fù","jiā"],meaning:"使家富足。富字拆解：宀（家）+一（一）+口（人口）+田（田产）——在家里守住那个一，从日常开始持续耕耘。"},{term:"假",pinyin:["gé"],meaning:"至、到达。亦读 jiǎ。「王假有家」：君主以德至于家，以身作则到家道之正。"},{term:"勿恤",pinyin:["wù","xù"],meaning:"不必忧虑。恤为忧虑、体恤。"},{term:"有孚"},{term:"威如",pinyin:["wēi","rú"],meaning:"威严自然显现的样子。「威如之吉，反身之谓也」：威不在外求，在反身自省。"},{term:"正家",pinyin:["zhèng","jiā"],meaning:"使家道端正。「正家而天下定矣」：家道正，则天下定。"},{term:"反身",pinyin:["fǎn","shēn"],meaning:"反求诸己、反身自省。治家的最高境界不是管人，是修身。"}]}),t[2]||(t[2]=r('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>家人卦上巽（风）下离（火），<strong>风自火出</strong>——火在内燃烧，风由内而生、向外扩散。</p><p>这正是一家之象：内明外顺，德风自内而出。家里有光（离为明），外就有风（巽为顺）；家内之火不熄，家外之风不止。家人卦讲的，就是这股由内而外、从家到天下扩散的德风。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p><strong>「正家而天下定矣」</strong>——这是家人卦的枢纽：家道正，则天下定。修身、齐家、治国、平天下的链条里，家是枢纽。</p><p>家道脉络，六爻一线：</p><ul><li><strong>立规矩</strong>（闲）→ <strong>守本位</strong>（中馈）→ <strong>拿捏严松</strong>（嗃嗃/嘻嘻）→ <strong>持续耕耘</strong>（富家）→ <strong>各司其职</strong>（勿恤）→ <strong>孚为根基</strong>（有孚威如）</li></ul><p>家不是退隐的角落，是治国的练习场——在家里练成的功夫，拿到天下一样能用。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>先立规矩：在志未变时立家规，趁早划清界限</li><li>守好本位：先耕好脚下的田，不抢别人的事做</li><li>严有度、松有祸：拿捏尺度，宁严勿松</li><li>持续耕耘：富是日积月累，不是一次拥有</li><li>从管控到信任：管到位之后放手</li><li>反身修己：威从孚来，先把自己做到</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><h3 id="框架一-家道脉络" tabindex="-1">框架一：家道脉络 <a class="header-anchor" href="#框架一-家道脉络" aria-label="Permalink to &quot;框架一：家道脉络&quot;">​</a></h3><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>初九</td><td>闲有家，悔亡</td><td>及早立规矩</td><td>门闩</td></tr><tr><td>六二</td><td>无攸遂，在中馈，贞吉</td><td>守本位，耕好脚下的田</td><td>中馈</td></tr><tr><td>九三</td><td>嗃嗃吉，嘻嘻吝</td><td>严有度，松有祸</td><td>拿捏</td></tr><tr><td>六四</td><td>富家，大吉</td><td>持续耕耘</td><td>富字模型</td></tr><tr><td>九五</td><td>王假有家，勿恤吉</td><td>从管控到信任</td><td>勿恤</td></tr><tr><td>上九</td><td>有孚威如，终吉</td><td>反身修己，威从孚来</td><td>孚</td></tr></tbody></table><h3 id="框架二-富字模型" tabindex="-1">框架二：富字模型 <a class="header-anchor" href="#框架二-富字模型" aria-label="Permalink to &quot;框架二：富字模型&quot;">​</a></h3><p><strong>宀 + 一 + 口 + 田</strong>——屋顶之下，守住那个「一」，养活那几口人，耕耘那片田。</p><p>富家不是发财，是<strong>在家里守住那个一、从日常开始持续耕耘</strong>。富的功夫不在别处，就在一日三餐、一蔬一饭的重复里——每一次认真经营，都在为家积一分富。</p><h3 id="框架三-信任成熟曲线" tabindex="-1">框架三：信任成熟曲线 <a class="header-anchor" href="#框架三-信任成熟曲线" aria-label="Permalink to &quot;框架三：信任成熟曲线&quot;">​</a></h3><p><strong>嗃嗃 → 中馈 → 勿恤</strong>：</p><ul><li><strong>嗃嗃</strong>（初九）——立规严管的起点，规矩要硬</li><li><strong>中馈</strong>（六二）——守位自持的过渡，各归其位</li><li><strong>勿恤</strong>（九五）——放手信任的到达，不必再忧</li></ul><p>严是信任的起点，信是严的终点；中间隔着六四的持续耕耘。<strong>没有前面的严，就没有后面的信；跳过耕耘的信任，是放纵。</strong></p><h3 id="框架四-孚的展开" tabindex="-1">框架四：孚的展开 <a class="header-anchor" href="#框架四-孚的展开" aria-label="Permalink to &quot;框架四：孚的展开&quot;">​</a></h3><p><strong>孚 → 威 → 敬 → 爱 → 感 → 终吉</strong>：</p><ul><li><strong>孚</strong>（诚信为根基）→ <strong>威</strong>（威严自然显现）→ <strong>敬</strong>（家人由敬生畏）→ <strong>爱</strong>（敬久生爱）→ <strong>感</strong>（爱能感人）→ <strong>终吉</strong></li></ul><p>治家的最高境界，是让家人因孚而自正，而非因威而惧服。威是孚的影子——影子是摆不出来的，光到了，影子自然在。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p><strong>家是最小的国，国是最大的家。</strong> 家人卦把「治国」的秘密藏在了「治家」里——正家而天下定矣。</p><p>六个爻，是一条治家的时间线，也是一条修身的成长线：</p><ul><li><strong>初九</strong> → 立规：规矩要立在志未变时</li><li><strong>六二</strong> → 守位：先耕好脚下的田</li><li><strong>九三</strong> → 拿捏：严是节，松是祸</li><li><strong>六四</strong> → 耕耘：富是日积月累</li><li><strong>九五</strong> → 信任：管到位之后放手</li><li><strong>上九</strong> → 反身：威从孚来</li></ul><p>与睽卦对照，更能看清家人卦的分量：<strong>家人是合，睽是离。</strong> 合的关键不在严管，在各自正位、以孚相通——位正了，家自合；位乱了，家自睽。治家如此，治国如此，经营一个团队、一段关系，也是如此。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：睽（第三十八卦）——家人卦与睽卦互为综卦（上下相倒）：<strong>家人是合，睽是离</strong>。合则家道正，离则成睽。</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',32))])}}});export{x as __pageData,b as default};
